def min_lexicographical_string(s):
    s = deque(s)
    t = deque()
    u = []

    while s or t:
        if s and (not t or s[0] <= t[-1]):
            t.appendleft(s.popleft())
        else:
            u.append(t.pop())

    return ''.join(u[::-1])

