from sys import stdin, stdout

def min_lexicographical_string(s):
    stack = []
    result = []

    for char in s:
        stack.append(char)

    while stack:
        top_char = stack.pop()
        if not result or top_char <= result[-1]:
            result.append(top_char)
        else:
            while result and top_char < result[-1]:
                stack.append(result.pop())
            result.append(top_char)

    return ''.join(result)

